# Generated by Claude Opus 5.5 with human oversight

#' Apply human in the loop flags to long data
#'
#' Every row of `human_in_loop_table` is matched against every observation at
#' once. `NA` in `variable`, `sensor_serial_number`, `timestamp_utc_min` or
#' `timestamp_utc_max` means "any". Timestamps are inclusive. A row with
#' `qc_flag_value` only flags observations where `<qc_test>_flag` has that
#' value. When several rows match an observation, the highest flag wins.
#'
#' @param dat Long data, one row per observation and variable, with `row_id`,
#'   `station`, `deployment_range`, `variable`, `sensor_serial_number`,
#'   `timestamp_utc`, and a `<qc_test>_flag` column for each `qc_test` named in
#'   the table.
#' @param human_in_loop_table The rows of the human in the loop table for the
#'   deployment in `dat`, already checked by `qc_test_human_in_loop()`, with
#'   `qc_test` and `qc_flag_value` columns.
#'
#' @return `dat` with the same rows in the same order, plus `human_in_loop_flag`
#'   (integer, 1 to 4; 1 when no table row applies) and `hil_comment`. Comments
#'   belong to the observation (`row_id`), not the variable: every variable of a
#'   `row_id` gets all comments that apply to any of its variables, pasted with
#'   "; " in table order. Warns for each table row that matches no observations.
#'
#' @importFrom dplyr arrange coalesce cross_join distinct filter group_by left_join matches mutate row_number select summarise
#' @importFrom tidyr pivot_longer
#'
#' @noRd
qc_core_human_in_loop <- function(dat, human_in_loop_table) {
  hil <- human_in_loop_table |>
    mutate(hil_row = row_number())

  # NA in the table means "any"
  # use cross_join because regular joins can't match an input value with NA
  hits <- dat |>
    select(row_id, variable, sensor_serial_number, timestamp_utc) |>
    cross_join(
      hil |>
        select(
          hil_row,
          hil_variable = variable,
          hil_serial = sensor_serial_number,
          timestamp_utc_min,
          timestamp_utc_max,
          qc_test,
          qc_flag_value,
          human_in_loop_flag_value,
          hil_comment
        )
    ) |>
    filter(
      is.na(hil_variable) | variable == hil_variable,
      is.na(hil_serial) | sensor_serial_number == hil_serial,
      is.na(timestamp_utc_min) | timestamp_utc >= timestamp_utc_min,
      is.na(timestamp_utc_max) | timestamp_utc <= timestamp_utc_max
    )

  # keep only observations where qc_test gave qc_flag_value
  if (any(!is.na(hil$qc_flag_value))) {
    ref_flags <- dat |>
      select(
        row_id,
        variable,
        matches("^(climatology|grossrange|rolling_sd|spike)_flag$")
      ) |>
      pivot_longer(
        -c(row_id, variable),
        names_to = "qc_test",
        names_pattern = "^(.+)_flag$",
        values_to = "ref_flag"
      )

    hits <- hits |>
      left_join(ref_flags, by = c("row_id", "variable", "qc_test")) |>
      filter(is.na(qc_flag_value) | ref_flag == qc_flag_value)
  }

  unused_rows <- setdiff(hil$hil_row, hits$hil_row)
  if (length(unused_rows) > 0) {
    warning(
      "human_in_loop_table row(s) for << ",
      paste(unique(dat$station), unique(dat$deployment_range)),
      " >> matched no observations. Check variable, sensor_serial_number, ",
      "timestamps and qc_flag_value:\n",
      paste(
        utils::capture.output(
          print(as.data.frame(
            select(filter(hil, hil_row %in% unused_rows), -hil_row)
          ))
        ),
        collapse = "\n"
      ),
      call. = FALSE
    )
  }

  # highest flag for each observation and variable
  hil_flags <- hits |>
    group_by(row_id, variable) |>
    summarise(
      human_in_loop_flag = as.integer(max(human_in_loop_flag_value)),
      .groups = "drop"
    )

  # comments for each observation, in table order
  hil_comments <- hits |>
    filter(!is.na(hil_comment)) |>
    distinct(row_id, hil_row, hil_comment) |>
    arrange(row_id, hil_row) |>
    group_by(row_id) |>
    summarise(
      hil_comment = paste(unique(hil_comment), collapse = "; "),
      .groups = "drop"
    )

  dat |>
    left_join(hil_flags, by = c("row_id", "variable")) |>
    left_join(hil_comments, by = "row_id") |>
    mutate(human_in_loop_flag = coalesce(human_in_loop_flag, 1L))
}
